import numpy as np

def normalize(x):
    x = np.asarray(x, dtype=float)
    lo, hi = np.nanmin(x), np.nanmax(x)
    if hi == lo:
        return np.zeros_like(x)
    return (x - lo) / (hi - lo)

import numpy as np

def batch_sums(x, size=4):
    out = []
    for i in range(0, len(x), size):
        out.append(x[i:i + size].sum())
    return out

import numpy as np

def pct_rank(x):
    x = np.asarray(x, dtype=float)
    order = x.argsort().argsort()
    return order / (len(x) - 1) * 100 if len(x) > 1 else np.zeros_like(x)
